    _postConstructor: function (cfg) {
        rh.dayoff.mpmt.acquisitionperiod.Window.superclass._postConstructor.call(this, cfg);
        this.on({
            scope: this,
            afterrender: function () {
                var scope = this;

                setTimeout(
                    function () {
                        var value = scope.getAutomaticCreatedField().getValue();
                        scope.getStartDateAcquisitionField().setReadOnly(value);
                        scope.getEndDateAcquisitionField().setReadOnly(value);
                        scope.getStartDateFruitionField().setReadOnly(value);
                        scope.getEndDateFruitionField().setReadOnly(value);

                        if (!scope.oId) {
                            scope.getGroupPeriodField().setReadOnly(false);
                            scope.getEmployeeField().setReadOnly(false);
                            scope.getStatusField().setReadOnly(false);
                            scope.getInformationField().setReadOnly(false);
                            scope.getPreviousPeriodField().setReadOnly(false);
                            scope.getContinuousPeriodField().setReadOnly(false);
                            scope.getBlockedField().setReadOnly(false);
                            scope.getPaidDaysCacheField().setReadOnly(false);
                            scope.getPaidWithoutPayrollField().setReadOnly(false);
                            scope.getIndemnifiedField().setReadOnly(false);
                            scope.getSuspendedDaysField().setReadOnly(false);
                            scope.getPaycheckEventField().setReadOnly(false);
                        }
                    },
                    500
                );
            }
        });
    },

