        var start_date =  this.getSuspensionStartDate(cfg).getValue()
        var end_date =  this.getSuspensionEndDate(cfg).getValue()
        var suspension_date = this.getSuspensionDate(cfg).getValue()

        if (suspension_date)
            return true
        else
            this.getSuspensionDate(cfg).setValue(null)

